    public sealed class ChaptersScreenController : IUomdScreenController
    {
        private readonly UomdSceneRouter _router;
        public UomdScreenId ScreenId => UomdScreenId.Chapters;

        public ChaptersScreenController(UomdSceneRouter router) => _router = router;

        public Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            var panel = new VisualElement();
            panel.AddToClassList("uomd-panel");

            string suffix = _router.Session.HardModeSelected ? "_hard" : "";
            var title = new Label(_router.Session.HardModeSelected
                ? "PART I CAMPAIGN — HARD MODE (ch01_s01_battle_hard .. ch07_s05_boss_hard)"
                : "PART I CAMPAIGN — CHAPTERS 1 TO 7");
            title.AddToClassList("uomd-title-md");
            panel.Add(title);

            for (int ch = 1; ch <= 7; ch++)
            {
                int chapterNum = ch;
                var row = new VisualElement();
                row.AddToClassList("uomd-card");
                row.style.flexDirection = FlexDirection.Row;
                row.style.justifyContent = Justify.SpaceBetween;
                row.style.marginTop = 8;

                var lbl = new Label($"Chapter {chapterNum}: ch0{chapterNum}_s01_battle{suffix} — First-Clear & 3★ Rewards");
                lbl.AddToClassList("uomd-body");

                var launchBtn = UomdUiKit.CreateButton("DEPLOY SQUAD", () =>
                {
                    _router.Session.ActiveBattleEncounterId = $"ch0{chapterNum}_s01_battle{suffix}";
                    _ = _router.NavigateToAsync(UomdScreenId.Battle);
                }, primary: true);

                row.Add(lbl);
                row.Add(launchBtn);
                panel.Add(row);
            }

            screenRoot.Add(panel);
            return default;
        }

        public void OnTick(float deltaTime) { }
        public void OnExit() { }
    }

