    public sealed class CharacterScreenController : IUomdScreenController
    {
        private readonly UomdSceneRouter _router;
        private string _activeTab = "OVERVIEW";
        private Label _tabBodyLabel;

        public UomdScreenId ScreenId => UomdScreenId.Character;

        public CharacterScreenController(UomdSceneRouter router) => _router = router;

        public Awaitable OnEnterAsync(VisualElement screenRoot)
        {
            string unitId = _router.Session.SelectedUnitId ?? "fadyme";
            var stats = UomdStatMath.ComputeHeroStats("TACTICIAN", 20, 2);

            var panel = new VisualElement();
            panel.AddToClassList("uomd-panel");

            var title = new Label($"CHARACTER INSPECTOR · {unitId.ToUpperInvariant()}");
            title.AddToClassList("uomd-title-md");
            panel.Add(title);

            // R10 Companion Growth Legibility Tabs: OVERVIEW | LEVEL | ASCEND | SKILLS
            var tabRow = new VisualElement();
            tabRow.style.flexDirection = FlexDirection.Row;
            tabRow.style.marginTop = 12;

            string[] tabs = { "OVERVIEW", "LEVEL", "ASCEND", "SKILLS" };
            for (int i = 0; i < tabs.Length; i++)
            {
                string tabName = tabs[i];
                var tabBtn = UomdUiKit.CreateButton(tabName, () =>
                {
                    _activeTab = tabName;
                    RefreshTabBody(unitId, stats);
                });
                tabBtn.style.marginRight = 8;
                tabRow.Add(tabBtn);
            }

            _tabBodyLabel = new Label();
            _tabBodyLabel.AddToClassList("uomd-body");
            _tabBodyLabel.style.marginTop = 16;

            panel.Add(tabRow);
            panel.Add(_tabBodyLabel);
            screenRoot.Add(panel);

            RefreshTabBody(unitId, stats);
            return default;
        }

        private void RefreshTabBody(string unitId, HeroDerivedStats stats)
        {
            _tabBodyLabel.text = _activeTab switch
            {
                "LEVEL" => $"[LEVEL UP] {unitId} · STR {stats.Str} | INT {stats.Int} | VIT {stats.Vit} | AGI {stats.Agi}",
                "ASCEND" => $"[ASCENSION] Unlocks tier stat multiplier & signature passive.",
                "SKILLS" => $"[SKILLS] Basic, Active, and Ultimate bound to §4.2 Signature VFX preset.",
                _ => $"[OVERVIEW] HP {stats.Hp} · ATK {stats.Atk} · DEF {stats.Def} · SPD {stats.Spd} · Crit {stats.CritRate:P1}"
            };
        }

        public void OnTick(float deltaTime) { }
        public void OnExit() { }
    }

